#!/usr/bin/env node
/**
 * L1 codegen：引擎真相层 -> 条目骨架（@generated，禁手改）
 * 骨架携带 engineRef.fingerprint；释义一律写入 src/data/<domain>/content/*.ts。
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');

async function loadEngine(modulePath) {
  try {
    return await import(modulePath);
  } catch (err) {
    console.warn(`[gen-content-skeleton] 无法加载 ${modulePath}：${String(err)}`);
    return null;
  }
}

async function main() {
  const div = await loadEngine('@temposoul/core/divination');

  if (div?.tarotCards?.length) {
    const body = `// @generated by scripts/gen-content-skeleton.mjs — DO NOT EDIT
// domain: tarot
// source: tarotCards (@temposoul/core/divination)

import { tarotCards } from '@temposoul/core/divination';
import type { ContentSkeleton } from '@/data/content/types';
import { makeEngineRef } from '@/data/content/fingerprint';

const SUIT_SLUG: Record<string, string> = {
  '权杖': 'wands', '圣杯': 'cups', '宝剑': 'swords', '星币': 'pentacles',
  wands: 'wands', cups: 'cups', swords: 'swords', pentacles: 'pentacles',
};

function suitSlug(suit?: string | null): string {
  if (!suit) return 'minor';
  return SUIT_SLUG[suit] ?? String(suit).toLowerCase();
}

function toSlug(card: { name: string; number: number; suit?: string | null }): string {
  const raw = card.suit ? \`\${suitSlug(card.suit)}-\${card.name}\` : String(card.name);
  const ascii = raw
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-\$)/g, '');
  return ascii.length > 0 ? ascii : \`\${card.suit ? suitSlug(card.suit) : 'major'}-\${String(card.number)}\`;
}

export const TAROT_SKELETONS: ContentSkeleton[] = tarotCards.map((card, index) => {
  const slug = toSlug(card);
  const category = card.type === '大阿卡纳' ? 'major' : suitSlug(card.suit);
  return {
    id: slug,
    slug,
    title: card.name,
    category,
    order: index,
    engineRef: makeEngineRef('@temposoul/core/divination#tarotCards', {
      name: card.name,
      number: card.number,
      suit: card.suit ?? null,
    }),
    domainFields: { cardNumber: card.number, arcana: card.type, suit: card.suit ?? null },
  };
});
`;
    const out = resolve(ROOT, 'src/data/tarot/generated/skeletons.ts');
    mkdirSync(dirname(out), { recursive: true });
    writeFileSync(out, body, 'utf8');
    console.log(`[gen-content-skeleton] tarot skeletons: ${div.tarotCards.length} -> ${out}`);
  }

  if (div?.hexagramsData?.length) {
    const body = `// @generated by scripts/gen-content-skeleton.mjs — DO NOT EDIT
// domain: yijing
// source: hexagramsData / trigramsByIndex (@temposoul/core/divination)

import { hexagramsData, trigramsByIndex } from '@temposoul/core/divination';
import type { ContentSkeleton } from '@/data/content/types';
import { makeEngineRef } from '@/data/content/fingerprint';

const PINYIN: Record<string, string> = {
  乾: 'qian', 坤: 'kun', 屯: 'zhun', 蒙: 'meng', 需: 'xu', 讼: 'song',
  师: 'shi', 比: 'bi', 小畜: 'xiaoxu', 履: 'lu', 泰: 'tai', 否: 'pi',
  同人: 'tongren', 大有: 'dayou', 谦: 'qian', 豫: 'yu', 随: 'sui', 蛊: 'gu',
  临: 'lin', 观: 'guan', 噬嗑: 'shihe', 贲: 'bi', 剥: 'bo', 复: 'fu',
  无妄: 'wuwang', 大畜: 'daxu', 颐: 'yi', 大过: 'daguo', 坎: 'kan', 离: 'li',
  咸: 'xian', 恒: 'heng', 遁: 'dun', 大壮: 'dazhuang', 晋: 'jin', 明夷: 'mingyi',
  家人: 'jiaren', 睽: 'kui', 蹇: 'jian', 解: 'xie', 损: 'sun', 益: 'yi',
  夬: 'guai', 姤: 'gou', 萃: 'cui', 升: 'sheng', 困: 'kun', 井: 'jing',
  革: 'ge', 鼎: 'ding', 震: 'zhen', 艮: 'gen', 渐: 'jian', 归妹: 'guimei',
  丰: 'feng', 旅: 'lu', 巽: 'xun', 兑: 'dui', 涣: 'huan', 节: 'jie',
  中孚: 'zhongfu', 小过: 'xiaoguo', 既济: 'jiji', 未济: 'weiji',
};

export const HEXAGRAM_SKELETONS: ContentSkeleton[] = hexagramsData.map((h) => {
  const slugBase = (PINYIN[h.name] ?? h.name).toLowerCase();
  const no = String(h.id).padStart(2, '0');
  const slug = \`\${no}-\${slugBase}\`;
  return {
    id: slug,
    slug,
    title: h.name,
    category: 'hexagram',
    order: h.id,
    engineRef: makeEngineRef('@temposoul/core/divination#hexagramsData', {
      id: h.id,
      name: h.name,
      symbol: h.symbol,
      upper: h.upper,
      lower: h.lower,
    }),
    domainFields: {
      hexagramNumber: h.id,
      symbol: h.symbol,
      binarySymbol: h.binarySymbol,
      upper: h.upper,
      lower: h.lower,
      palace: h.palace,
      upperTrigram: (trigramsByIndex as Record<number, unknown>)?.[h.upper] ?? null,
      lowerTrigram: (trigramsByIndex as Record<number, unknown>)?.[h.lower] ?? null,
    },
  };
});
`;
    const out = resolve(ROOT, 'src/data/yijing/generated/skeletons.ts');
    mkdirSync(dirname(out), { recursive: true });
    writeFileSync(out, body, 'utf8');
    console.log(`[gen-content-skeleton] yijing skeletons: ${div.hexagramsData.length} -> ${out}`);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
